#include <stdio.h>
int main(void) {
    int i, sum = 0;
    for (i = 1; i <= 5; i++) {
        sum += i;
    }
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>
int main(void) {
    int i = 0;
    while (i < 3) {
        printf("%d ", i);
        i++;
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int i = 5;
    do {
        printf("%d ", i);
        i--;
    } while (i > 5);
    printf("\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int i, j;
    for (i = 1; i <= 2; i++) {
        for (j = 1; j <= 3; j++) {
            printf("%d ", i * j);
        }
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int i;
    for (i = 0; i < 10; i++) {
        if (i == 3) {
            break;
        }
        printf("%d ", i);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int i;
    for (i = 0; i < 5; i++) {
        if (i % 2 == 0) {
            continue;
        }
        printf("%d ", i);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int i, j;
    for (i = 1; i <= 3; i++) {
        for (j = 1; j <= i; j++) {
            printf("*");
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int i, j;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            if (j == 1) {
                break;
            }
            printf("%d ", i * 10 + j);
        }
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int i, count = 0;
    for (i = 1; i <= 20; i++) {
        if (i % 3 == 0) {
            continue;
        }
        if (i % 5 == 0) {
            break;
        }
        count++;
    }
    printf("%d\n", count);
    return 0;
}
